new='''impl<'input, 'arena> Visitor<'input, 'arena> for RemoveEmptyContainers {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }
        context.query_has_stylesheet(document);
        context.query_has_script(document);
        let implicated = Implicated::collect(document, &context.query_has_stylesheet_result)?;
        let state = State {
            options: self,
            implicated,
        };
        state.start_with_context(document, context)?;
        Ok(PrepareOutcome::skip)
    }
}

struct State<'o, 'input, 'arena> {
    options: &'o RemoveEmptyContainers,
    implicated: Implicated<'input, 'arena>,
}

impl<'input, 'arena> Visitor<'input, 'arena> for State<'_, 'input, 'arena> {
    type Error = JobsError<'input>;

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let name = element.qual_name();

        if !name.categories().contains(ElementCategory::Container) || !element.is_empty() {
            return Ok(());
        }
        if is_element!(element, Svg) {
            return Ok(());
        } else if is_element!(element, Pattern) {
            if !element.attributes().is_empty() {
                return Ok(());
            }
        } else if is_element!(element, Mask) {
            if has_attribute!(element, Id) {
                return Ok(());
            }
        } else if element
            .parent_element()
            .is_some_and(|e| is_element!(e, Switch))
        {
            return Ok(());
        }
        if is_element!(element, G) {
            let computed_styles = ComputedStyles::default()
                .with_all(element, &context.query_has_stylesheet_result)
                .map_err(JobsError::ComputedStylesError)?;
            if has_computed_style!(computed_styles, Filter) {
                return Ok(());
            }
        }
        if removal_would_affect_implicated(element, &self.implicated) {
            return Ok(());
        }

        element.remove();
        Ok(())
    }
}

fn removal_would_affect_implicated<'input, 'arena>(
    element: &Element<'input, 'arena>,
    implicated: &Implicated<'input, 'arena>,
) -> bool {
    if implicated.contains(element) {
        log::debug!("remove_empty_containers: not removing: implicated element");
        return true;
    }
    if element
        .parent_element()
        .is_some_and(|parent| implicated.contains(&parent))
    {
        log::debug!("remove_empty_containers: not removing: implicated parent");
        return true;
    }
    let mut sibling = element.next_element_sibling();
    while let Some(sibling) = sibling {
        if implicated.contains(&sibling) {
            log::debug!("remove_empty_containers: not removing: implicated following sibling");
            return true;
        }
        sibling = sibling.next_element_sibling();
    }
    false
}'''
